const items = $('When Executed by Another Workflow').all();

const now = new Date();
const formattedDate =
  now.toLocaleDateString('id-ID', {
    day: '2-digit',
    month: 'long',
    year: 'numeric',
    timeZone: 'Asia/Jakarta'
  }) +
  ', ' +
  now.toLocaleTimeString('id-ID', {
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
    timeZone: 'Asia/Jakarta'
  });

for (const item of items) {
  const body = item.json.body ?? item.json;

  const template = `*🔔 Inquiry Baru dari TASIA*
━━━━━━━━━━━━━━━━
📅 Waktu: ${formattedDate}
👤 Customer: ${body.customerName}
📱 Telepon: ${body.customerPhone}
🏢 Cabang: ${body.branchCode}
📋 Tipe: ${body.InquiryType}
📋 *Ringkasan:*
${body.summary}
━━━━━━━━━━━━━━━━
Mohon segera follow-up customer ini.`;

  item.json = {
    ...body,
    notification: template,
    dateTime: formattedDate,
    inquiryType: body.inquiryType,
    initialQuestion: body.initialQuestion,
    consent: body.consent,
    nextAction: body.nextAction,
    policeRegNo: body.PoliceRegNo,
    messageId: body.messageId,
    conversationId: body.conversationId
  };
}
return items;

